import base64
text = ""

text = text[::-1]
array = text[:1010]
array = [array[i:i+101] for i in range(0,len(array),101)]
array = [i[1:] for i in array]
array = ''.join(array)

array2 = text[1010:]
array2 = [array2[i:i+1001] for i in range(0,len(array2),1001)]
array2 = [i[1:] for i in array2]
array2 = ''.join(array2)

array = array + array2
if len(array) % 1000 !=0:
    array = array[:-1]
str = base64.b64decode(array)